import{_ as d,C as c,o as t,c as i,a2 as a,b as n,w as r,a as s,E as l,a3 as m}from"./chunks/framework.DZUUNQ77.js";const D=JSON.parse('{"title":"Daemon 保活机制","description":"","frontmatter":{},"headers":[],"relativePath":"reference/client/stub-daemon.md","filePath":"reference/client/stub-daemon.md","lastUpdated":1784053534000}'),b={name:"reference/client/stub-daemon.md"};function h(v,e,u,p,E,S){const o=c("Mermaid");return t(),i("div",null,[e[1]||(e[1]=a('<h1 id="daemon-保活机制" tabindex="-1">Daemon 保活机制 <a class="header-anchor" href="#daemon-保活机制" aria-label="Permalink to &quot;Daemon 保活机制&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">源码路径</p><p><a href="https://github.com/android-security-engineer/VirtualXposed-skills/blob/vxp/VirtualApp/lib/src/main/java/com/lody/virtual/client/stub/DaemonService.java" target="_blank" rel="noreferrer"><code>src/main/java/com/lody/virtual/client/stub/DaemonService.java</code></a> + <code>DaemonJobService.java</code></p></div><p><code>DaemonService</code> 与 <code>DaemonJobService</code> 配合保活 server 进程。Android 后台进程容易被系统回收，一旦 server 挂了，所有虚拟 App 的 binder 调用都断。这两个组件用「前台 Service + JobScheduler」双保险把 server 拉起来。</p><h2 id="daemonservice" tabindex="-1">DaemonService <a class="header-anchor" href="#daemonservice" aria-label="Permalink to &quot;DaemonService&quot;">​</a></h2><table tabindex="0"><thead><tr><th>成员</th><th>作用</th></tr></thead><tbody><tr><td><code>startup(Context)</code></td><td>启动守护 Service</td></tr><tr><td><code>onStartCommand(...)</code></td><td>设为前台 Service（带通知）</td></tr><tr><td><code>InnerService</code></td><td>内部 Service，进一步提优先级</td></tr><tr><td><code>showNotification</code></td><td>是否显示保活通知（<code>NOTIFY_ID=1001</code>）</td></tr><tr><td><code>onDestroy()</code></td><td>被杀时重新拉起</td></tr></tbody></table><p>前台 Service 让进程优先级提到「前台」级别，降低被低内存杀手回收的概率。</p><h2 id="daemonjobservice" tabindex="-1">DaemonJobService <a class="header-anchor" href="#daemonjobservice" aria-label="Permalink to &quot;DaemonJobService&quot;">​</a></h2><table tabindex="0"><thead><tr><th>成员</th><th>作用</th></tr></thead><tbody><tr><td><code>scheduleJob(Context)</code></td><td>用 <code>JobScheduler</code> 注册周期任务</td></tr><tr><td><code>onStartJob(...)</code></td><td>周期触发，检查 server 是否存活，不在则拉起</td></tr><tr><td><code>onStopJob(...)</code></td><td>返回 true 让任务重新调度</td></tr></tbody></table><p>JobScheduler 在系统空闲时仍能周期唤醒，作为 Service 被杀后的兜底拉起手段。</p><h2 id="双保险逻辑" tabindex="-1">双保险逻辑 <a class="header-anchor" href="#双保险逻辑" aria-label="Permalink to &quot;双保险逻辑&quot;">​</a></h2>',10)),(t(),n(m,null,{default:r(()=>[l(o,{id:"mermaid-118",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E8%BF%9B%E7%A8%8B%E8%A2%AB%E6%9D%80%22%5D%20--%3E%20B%7B%22DaemonService%3Cbr%2F%3E%E5%89%8D%E5%8F%B0%20Service%20%E8%BF%98%E5%9C%A8%3F%22%7D%0A%20%20B%20--%3E%7C%E6%98%AF%7C%20C%5B%22onDestroy%20%E6%8B%89%E8%B5%B7%22%5D%0A%20%20B%20--%3E%7C%E5%90%A6%7C%20D%5B%22JobScheduler%3Cbr%2F%3E%E5%91%A8%E6%9C%9F%E8%A7%A6%E5%8F%91%22%5D%0A%20%20D%20--%3E%20E%5B%22DaemonJobService%3Cbr%2F%3E%E6%A3%80%E6%9F%A5%E5%B9%B6%E6%8B%89%E8%B5%B7%20server%22%5D%0A%20%20C%20--%3E%20F%5B%22server%20%E6%81%A2%E5%A4%8D%22%5D%0A%20%20E%20--%3E%20F%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="./va-settings"><code>VASettings</code></a>：保活相关开关。</li><li><a href="./../../architecture/process-model">进程模型</a>：server 进程地位。</li><li><a href="./../../features/ipc-bridge">IPC 桥</a>：为什么 server 不能挂。</li></ul>',2))])}const A=d(b,[["render",h]]);export{D as __pageData,A as default};
